import {db,fs} from '/tmp/handoff-eleven.mjs';
const jobs=JSON.parse(fs.readFileSync('artifacts/realtor-batch-20261009/live-status.json')).jobs;
const ids=new Set(jobs.map(j=>j.contact_id));let t=[];for(let offset=0;;offset+=1000){const p=await db('market_touches',{direction:'eq.inbound',created_at:'gte.2026-10-09T04:00:00Z',select:'contact_id,channel,notes,created_at',order:'created_at.asc,id.asc',limit:'1000',offset:String(offset)});t.push(...p);if(p.length<1000)break;}
const contactIds=[...new Set(t.map(x=>x.contact_id))];let cs=[];for(let i=0;i<contactIds.length;i+=100)cs.push(...await db('market_contacts',{id:'in.('+contactIds.slice(i,i+100).join(',')+')',select:'id,name,phone,city'}));const cm=new Map(cs.map(c=>[c.id,c]));const key=x=>String(cm.get(x.contact_id)?.phone||x.contact_id).replace(/\D/g,'').slice(-10)||x.contact_id;const count=a=>new Set(a.map(key)).size;const batch=t.filter(x=>ids.has(x.contact_id));
console.log(JSON.stringify({at:new Date().toISOString(),todayAllUnique:count(t),todayAllSmsUnique:count(t.filter(x=>x.channel==='sms')),todayBatchUnique:count(batch),todayBatchSmsUnique:count(batch.filter(x=>x.channel==='sms')),todayBatchInboundSms:batch.filter(x=>x.channel==='sms').length,newSinceLast:t.filter(x=>x.created_at>'2026-10-09T22:40:45Z').map(x=>({name:cm.get(x.contact_id)?.name,at:x.created_at,text:x.notes}))},null,2));
